 function pageRows(kind){let rows=dataRows(kind);if(kind==='enrollments'&&['transfer','withdraw','supplement'].includes(state.page)){const states=state.page==='transfer'?['active','在读','已生效']:state.page==='withdraw'?['active','pending','paid','在读','待生效','已生效','已付清']:['pending','paid','unpaid','待收款','部分付款'];rows=rows.filter(r=>states.includes(r.status))}if(kind==='enrollments'&&state.page==='tempMove')rows=rows.filter(r=>['active','在读','已生效'].includes(r.status));if(kind==='sessionAdjustments'&&['makeup','tempMove'].includes(state.page))rows=rows.filter(r=>r.kind===(state.page==='makeup'?'makeup':'temporary'));if(kind==='orders'&&['financeArrears','supplement'].includes(state.page))rows=rows.filter(outstandingOrder);if(kind==='courses'&&state.page==='mallShelf'){const shelf=new Set((ui.data?.shelved||[]).map(x=>typeof x==='string'?x:x.courseId)),hidden=new Set(ui.data?.hiddenShelved||[]);rows=rows.map(r=>({...r,storefrontStatus:!shelf.has(r.id)?'未上架':hidden.has(r.id)?'已下架':'已上架'}))}if(kind==='students'&&state.page==='learningActive'){const active=new Set(dataRows('enrollments').filter(e=>['active','在读','已生效'].includes(e.status)).map(e=>e.studentId));rows=rows.filter(s=>active.has(s.id))}if(kind==='students'&&state.page==='learningHistory'){const active=new Set(dataRows('enrollments').filter(e=>['active','在读','已生效'].includes(e.status)).map(e=>e.studentId)),historic=new Set(dataRows('enrollments').filter(e=>['withdrawn','completed','已退课','已完成'].includes(e.status)&&!!e.activatedAt).map(e=>e.studentId));rows=rows.filter(s=>!active.has(s.id)&&historic.has(s.id))}return rows}
