  if(page==='leadManage')rows=rows.filter(({row,timing})=>ui.leadManageTab==='all'||(ui.leadManageTab==='archived'?leadArchived(row):ui.leadManageTab==='decision'?row.decisionStatus==='pending'&&(row.decisionById||row.ownerId)===ui.user.id:!leadArchived(row)&&!leadConverted(row)&&(ui.leadManageTab==='public'?!row.ownerId:ui.leadManageTab==='assigned'?!!row.ownerId:timing.recycle)));
