 function leadAction(id,operation){const row=dataRows('leads').find(r=>leadIdentity(r)===id),op=ui.operations.find(o=>o.id===operation);if(!row||!permitted(op)||(!leadWritable(row)&&!(operation==='lead.reclaim.request'&&!row.ownerId&&row.decisionStatus==='timed_out'&&!leadConverted(row))))return false;if(row.decisionStatus==='pending'&&!leadCanDecide(row))return false;return open(operation,seedFor('leads',row,op))}

 async function attendanceRosterLoad(classId,sessionId){if(!classId||!sessionId)return false;const epoch=++ui.attendanceRosterEpoch,authEpoch=ui.epoch,key=classId+'|'+sessionId,operation=ui.operation?.id,current=()=>epoch===ui.attendanceRosterEpoch&&authEpoch===ui.epoch&&state.page==='businessOperation'&&ui.operation?.id===operation&&ui.draft.classId+'|'+ui.draft.sessionId===key;ui.attendanceRoster=null;ui.attendanceRosterFor=key;ui.attendanceRosterError='';ui.attendanceRosterBusy=true;draw();try{const result=await employeeAuth.request('v1/sessions/attendance-roster?'+new URLSearchParams({classId,sessionId}));if(!current())return false;if(!Array.isArray(result.roster)||result.roster.some(r=>!r||typeof r.studentId!=='string'||!['attended','late','left_early','leave','absent'].includes(r.attendanceStatus)||typeof r.locked!=='boolean')||new Set(result.roster.map(r=>r.studentId)).size!==result.roster.length)throw Error('服务器点名名单格式不完整，请刷新重试');ui.attendanceRoster=result.roster;if(operation==='session.attendance')ui.draft.rows=ui.attendanceRoster.map(row=>({studentId:row.studentId,status:row.attendanceStatus||'attended',note:row.note||'',...(row.recorded&&typeof row.consumptionConfirmed==='boolean'?{consume:row.consumptionConfirmed}:{})}));else if(!ui.attendanceExceptionsDirty)ui.draft.exceptions=ui.attendanceRoster.filter(row=>['leave','absent'].includes(row.attendanceStatus||row.status)).map(row=>({studentId:row.studentId,status:row.attendanceStatus||row.status,...(row.note?{note:row.note}:{})}));return true}catch(e){if(current())ui.attendanceRosterError=errorText(e);return false}finally{if(epoch===ui.attendanceRosterEpoch){ui.attendanceRosterBusy=false;if(current())draw()}}}
 async function makeupCandidatesLoad(enrollmentId,sourceSessionId){if(!enrollmentId||!sourceSessionId)return false;const epoch=++ui.makeupCandidatesEpoch,authEpoch=ui.epoch,key=enrollmentId+'|'+sourceSessionId;ui.makeupCandidates=null;ui.makeupCandidatesFor=key;ui.makeupCandidatesError='';ui.makeupCandidatesBusy=true;draw();try{const q=new URLSearchParams({enrollmentId,sourceSessionId}),result=await employeeAuth.request('v1/makeup/candidates?'+q);if(epoch!==ui.makeupCandidatesEpoch||authEpoch!==ui.epoch||state.page!=='businessOperation'||ui.operation?.id!=='makeup.assign'||ui.draft.kind!=='makeup'||ui.draft.enrollmentId+'|'+ui.draft.sourceSessionId!==key)return false;ui.makeupCandidates=Array.isArray(result.candidates)?result.candidates:[];return true}catch(e){if(epoch===ui.makeupCandidatesEpoch&&authEpoch===ui.epoch&&state.page==='businessOperation'&&ui.operation?.id==='makeup.assign'&&ui.draft.kind==='makeup'&&ui.draft.enrollmentId+'|'+ui.draft.sourceSessionId===key)ui.makeupCandidatesError=errorText(e);return false}finally{if(epoch===ui.makeupCandidatesEpoch){ui.makeupCandidatesBusy=false;if(state.page==='businessOperation'&&ui.operation?.id==='makeup.assign'&&ui.draft.kind==='makeup')draw()}}}
 function todayLocal(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
 function attendanceException(studentId,status){if(ui.busy||ui.uncertain||ui.operation?.id!=='session.attendance.exceptions')return false;const existing=(ui.draft.exceptions||[]).find(row=>row.studentId===studentId),rows=(ui.draft.exceptions||[]).filter(row=>row.studentId!==studentId);if(['leave','absent'].includes(status))rows.push({studentId,status,...(existing?.note?{note:existing.note}:{})});ui.draft.exceptions=rows;ui.attendanceExceptionsDirty=true;ui.preview=null;ui.key=null;ui.error='';draw();return true}
 function teacherFormField(key,schema,path){if(ui.operation?.id==='session.attendance.exceptions'&&key==='exceptions'){const keyId=ui.draft.classId+'|'+ui.draft.sessionId,roster=ui.attendanceRosterFor===keyId?ui.attendanceRoster:null,selected=new Map((ui.draft.exceptions||[]).map(x=>[x.studentId,x.status]));return `<div class="business-fieldset teacher-exception-roster"><strong>当天异常考勤</strong><p class="help">名单来自服务器当前课次名单；未选择的学生按正常到课处理。预览会再次核对名单。</p>${ui.attendanceRosterBusy?'<p class="muted">正在读取服务器当前名单…</p>':ui.attendanceRosterError?`<p class="business-error" role="alert">${html(ui.attendanceRosterError)}</p><button type="button" class="btn small" onclick="businessAPI.attendanceRosterRefresh()">重新读取名单</button>`:!roster?'<p class="muted">先选择班级和课次以读取名单。</p>':roster.length?`<div class="table-wrap"><table class="table business-table"><thead><tr><th>学生</th><th>考勤</th><th>备注</th></tr></thead><tbody>${roster.map(row=>`<tr><td>${html(row.name||nameOf('students',row.studentId))}</td><td><select class="input" aria-label="${html((row.name||'学生')+'考勤情况')}" onchange="businessAPI.attendanceException(${html(JSON.stringify(row.studentId))},this.value)"><option value="" ${!selected.has(row.studentId)?'selected':''}>正常到课</option><option value="leave" ${selected.get(row.studentId)==='leave'?'selected':''}>请假</option><option value="absent" ${selected.get(row.studentId)==='absent'?'selected':''}>旷课</option></select></td><td>${html(row.note||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">服务器当前名单为空，请刷新后确认。</p>'}</div>`}
  if(ui.operation?.id==='makeup.assign'&&ui.draft.kind==='makeup'&&key==='targetClassId'){const candidates=ui.makeupCandidatesFor===ui.draft.enrollmentId+'|'+ui.draft.sourceSessionId?ui.makeupCandidates||[]:[];return `<div class="business-fieldset"><label>可安排的目标课次</label><p class="help">候选项已由服务器校验空位、同课程和时间冲突；优先显示同一老师的可用课次。</p>${ui.makeupCandidatesBusy?'<p class="muted">正在查找实际可用课次…</p>':ui.makeupCandidatesError?`<p class="business-error" role="alert">${html(ui.makeupCandidatesError)}</p>`:!ui.draft.enrollmentId||!ui.draft.sourceSessionId?'<p class="muted">请先选择在读报名和原课次。</p>':candidates.length?`<select class="input" aria-label="目标课次" onchange="businessAPI.makeupCandidate(this.value)"><option value="">请选择可用课次</option>${candidates.map(c=>`<option value="${html(c.classId+'|'+c.sessionId)}" ${(ui.draft.targetClassId+'|'+ui.draft.targetSessionId)===(c.classId+'|'+c.sessionId)?'selected':''}>${html(`${c.date} ${c.time} · ${c.className} · ${c.teacherName||'老师'} · ${c.campus||''} ${c.room||''} · 余${c.availableSeats}位${c.sameTeacher?' · 同一老师':''}`)}</option>`).join('')}</select>`:'<p class="muted">当前没有符合条件的可用课次；可登记主动放弃。</p>'}<input type="hidden" data-business-path="[&quot;targetClassId&quot;]" data-business-type="string" value="${html(ui.draft.targetClassId||'')}"></div>`}
  if(ui.operation?.id==='makeup.assign'&&ui.draft.kind==='makeup'&&key==='targetSessionId')return `<input type="hidden" data-business-path="[&quot;targetSessionId&quot;]" data-business-type="string" value="${html(ui.draft.targetSessionId||'')}">`;
  if(ui.operation?.id==='session.reschedule.request'&&key==='time'){const start=(String(ui.draft.time||'').match(/^\d{2}:\d{2}/)||[''])[0];return `<div class="business-field"><label>新开始时间<span class="required-mark">*</span></label><input class="input" type="time" data-business-path="[&quot;time&quot;]" data-business-type="time-start" value="${html(start)}" onchange="businessAPI.change(['time'],this.value,'time-start')"><small class="help">结束时间会根据原课程讲次时长自动计算。</small></div>`}
  return null}
 function teacherSessions(){const today=todayLocal(),clock=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date()).split(':').map(Number),now=clock[0]*60+clock[1],entries=[];for(const c of dataRows('classes'))for(const s of c.schedule||[]){if((s.substituteTeacherId||s.teacherId||c.teacherId)!==ui.user?.id||['cancelled','canceled','已取消'].includes(String(s.status||'').toLowerCase())||s.date<today)continue;const hm=(String(s.time||'').match(/^(\d{2}):(\d{2})/)||[]).slice(1).map(Number),start=hm.length===2?hm[0]*60+hm[1]:0;entries.push({c,s,today:s.date===today,started:s.date===today&&start<=now,future:s.date>today||s.date===today&&start>now})}return entries.sort((a,b)=>String(a.s.date+' '+a.s.time).localeCompare(String(b.s.date+' '+b.s.time)))}
 function sessionDuration(c,s){const course=dataRows('courses').find(x=>x.id===c?.courseId),lesson=(course?.lessons||[]).find(x=>x.id===s?.lessonId);return Number(c?.durationMinutes??lesson?.durationMinutes)||0}
 function rescheduleSlot(start){const match=String(start||'').match(/^(\d{2}):(\d{2})$/);if(!match)return '';const c=dataRows('classes').find(x=>x.id===ui.draft.classId),s=(c?.schedule||[]).find(x=>x.id===ui.draft.sessionId),duration=sessionDuration(c,s);if(!duration)return '';const begin=Number(match[1])*60+Number(match[2]),end=begin+duration;if(end>=24*60)return '';const fmt=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;return `${fmt(begin)}–${fmt(end)}`}
 function teacherCoursesHtml(){const ops=ui.operations.filter(permitted),attendance=ops.find(o=>o.id==='session.attendance.exceptions'),reschedule=ops.find(o=>o.id==='session.reschedule.request'),rows=teacherSessions();return `<section class="card pad"><div class="toolbar"><strong>我的课程</strong><button class="btn" onclick="businessAPI.reload()">刷新</button></div><p class="help">按当前账号实际授课老师筛选。异常考勤仅可登记北京时间当天已开始的课次；正常到课由系统按服务器名单默认记录。</p><div class="table-wrap"><table class="table business-table"><thead><tr><th>日期</th><th>时间</th><th>班级</th><th>课程讲次</th><th>校区 / 教室</th><th>操作</th></tr></thead><tbody>${rows.map(({c,s,today,started,future})=>`<tr><td>${html(s.date||'—')}${today?' · 今天':''}</td><td>${html(s.time||'—')}</td><td>${html(c.name||'—')}</td><td>${html(lessonLabel(c,s.lessonId))}</td><td>${html(nameOf('campuses',s.campusId||c.campusId))} / ${html(s.room||c.room||'—')}</td><td><div class="mf-list-actions">${today&&started&&attendance?`<button type="button" onclick="businessAPI.open('session.attendance.exceptions',{classId:${html(JSON.stringify(c.id))},sessionId:${html(JSON.stringify(s.id))}})">登记异常考勤</button>`:''}${future&&reschedule?`<button type="button" onclick="businessAPI.open('session.reschedule.request',{classId:${html(JSON.stringify(c.id))},sessionId:${html(JSON.stringify(s.id))},date:${html(JSON.stringify(s.date))},time:${html(JSON.stringify((String(s.time||'').match(/^\d{2}:\d{2}/)||[''])[0]))}})">申请调课</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无本人授课课次</td></tr>'}</tbody></table></div></section>`}
