 function teacherMetricDetail(label,m){if(!m)return '';const rate=m.available&&m.rate!==null?`${(Number(m.rate)*100).toFixed(1)}%（${Number(m.numerator)||0} / ${Number(m.denominator)||0}）`:`数据不足（${Number(m.numerator)||0} / ${Number(m.denominator)||0}）`;return `<details class="teacher-metric-detail"><summary>${label}：${rate}</summary><p>${html(m.cohort||'统计人群未说明')}</p><p>${html(m.reason||'')}</p>${m.observationDays?`<p>观察窗：${Number(m.observationDays)} 天</p>`:''}${m.pendingObservation?`<p>待观察结课学生：${Number(m.pendingObservation)}</p>`:''}${m.unknownOrders?`<p>归因不完整订单：${Number(m.unknownOrders)}</p>`:''}</details>`}
