 function submissionSubmitter(submission){if(submission.submitterType==='public'||submission.submittedBy==='public'||!(submission.submitterId||submission.submittedBy))return '家长公开填写';return submission.submitterName||nameOf('directory',submission.submitterId||submission.submittedBy)||'员工提交'}
