 function submissionsHtml(){const purpose=f=>({lead:'线索登记',survey:'家长问卷',custom:'自定义表单'})[f.kind]||'其他表单',conversion=f=>f.kind==='lead'||f.kind==='custom'&&f.collectLead?'可转入线索':'不转入线索',beijingTime=value=>{if(typeof value!=='string'||!value)return '—';const date=new Date(value);if(!Number.isFinite(date.getTime()))return '—';const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).map(part=>[part.type,part.value]));return parts.year+'-'+parts.month+'-'+parts.day+' '+parts.hour+':'+parts.minute},rows=formSubmissionRows(),total=dataRows('forms').reduce((n,f)=>n+(f.submissions||[]).length,0),annotate=submissionAction('form.submission.annotate'),review=submissionAction('form.submission.review');return `<section class="business-stats"><div><span>可见提交</span><strong>${total}</strong></div><div><span>待审核</span><strong>${dataRows('forms').reduce((n,f)=>n+(f.submissions||[]).filter(s=>s.status==='pending').length,0)}</strong></div><div><span>已审核</span><strong>${dataRows('forms').reduce((n,f)=>n+(f.submissions||[]).filter(s=>s.status!=='pending').length,0)}</strong></div></section><section class="card pad"><div class="business-tabs" role="tablist"><button type="button" role="tab" onclick="nav('marketingForms')">表单管理</button>${[['pending','待审核'],['approved','已通过'],['rejected','已拒绝'],['all','全部']].map(([key,label])=>`<button type="button" role="tab" aria-selected="${ui.formSubmissionFilter===key}" class="${ui.formSubmissionFilter===key?'active':''}" onclick="businessAPI.formSubmissionTab('${key}')">${label}</button>`).join('')}</div><p class="notice">待审答案仅对发布者及审核授权人员可见。审核通过后，仅线索登记或明确开启收集线索的自定义表单会进入线索池；问卷不会创建销售线索。</p><div class="toolbar"><span class="muted">审核和标注均通过服务器授权操作留痕</span><button class="btn" onclick="businessAPI.reload()">刷新</button></div><div class="table-wrap"><table class="table business-table"><thead><tr><th>提交时间</th><th>表单</th><th>提交者</th><th>状态</th><th>答卷摘要</th><th>审核/标注</th></tr></thead><tbody>${rows.map(({form,submission})=>{const answers=Object.entries(submission.answersById||{}).map(([id,value])=>{const field=(submission.fieldSnapshot||form.fields||[]).find(x=>x.id===id);return `${field?.title||id}：${Array.isArray(value)?value.join('、'):value}`}),formId=form.id,submissionId=submission.id,canReview=submissionCanReview(submission);return `<tr><td>${html(beijingTime(submission.createdAt))}</td><td>${html(form.title||form.name||'未命名表单')}<small class="business-lead-guardian">${html(purpose(form))} · ${html(conversion(form))}</small></td><td>${html(submissionSubmitter(submission))}</td><td><span class="badge ${submission.status==='approved'?'':submission.status==='pending'?'off':'off'}">${html(({pending:'待审核',approved:'已通过',rejected:'已拒绝',legacy:'已入库（旧记录）'})[submission.status]||'状态未知')}</span></td><td>${html(answers.slice(0,3).join('；')||'无答案')}${answers.length>3?`<details><summary>其余 ${answers.length-3} 项</summary>${html(answers.slice(3).join('；'))}</details>`:''}${submissionBenefitsHtml(formId,submission)}${submission.note?`<small class="business-lead-guardian">标注：${html(submission.note)}</small>`:''}</td><td><div class="mf-list-actions">${submission.status==='pending'&&annotate&&canReview?`<button type="button" onclick="businessAPI.open('form.submission.annotate',{formId:${html(JSON.stringify(formId))},submissionId:${html(JSON.stringify(submissionId))},note:${html(JSON.stringify(submission.note||''))}})">添加标注</button>`:''}${submission.status==='pending'&&review&&canReview?`<button type="button" onclick="businessAPI.open('form.submission.review',{formId:${html(JSON.stringify(formId))},submissionId:${html(JSON.stringify(submissionId))},decision:'approve'})">审核通过</button><button type="button" class="danger" onclick="businessAPI.open('form.submission.review',{formId:${html(JSON.stringify(formId))},submissionId:${html(JSON.stringify(submissionId))},decision:'reject'})">拒绝</button>`:''}${submission.leadId?`<button type="button" onclick="businessAPI.leadDetail(${html(JSON.stringify(submission.leadId))})">查看线索</button>`:''}</div></td></tr>`}).join('')||`<tr><td colspan="6" class="empty">${ui.formSubmissionFilter==='pending'?'暂无待审核提交。新提交不会自动出现在销售线索中。':'暂无符合条件的提交'}</td></tr>`}</tbody></table></div></section>`}
 async function salesReportLoad(){if(!active()||!ui.user.permissions.some(x=>['report.read','lead.conversion.read'].includes(x)))return false;const epoch=ui.epoch,request=++ui.salesReportEpoch,from=ui.salesReportFrom,to=ui.salesReportTo;const params=new URLSearchParams();if(from)params.set('from',from);if(to)params.set('to',to);ui.salesReport=null;ui.salesReportBusy=true;ui.salesReportError='';draw();try{const result=await employeeAuth.request('v1/reports/sales'+(params.size?'?'+params:''));if(epoch!==ui.epoch||request!==ui.salesReportEpoch||!active()||state.page!=='salesMetrics'||ui.salesReportFrom!==from||ui.salesReportTo!==to)return false;ui.salesReport=result;return true}catch(e){if(epoch===ui.epoch&&request===ui.salesReportEpoch&&state.page==='salesMetrics'&&ui.salesReportFrom===from&&ui.salesReportTo===to)ui.salesReportError=errorText(e);return false}finally{if(epoch===ui.epoch&&request===ui.salesReportEpoch){ui.salesReportBusy=false;if(state.page==='salesMetrics')draw()}}}
