 async function salesFollowupsLoad(employeeId,cursor=''){
  if(!active()||!ui.user.permissions.some(x=>['audit.read','sales.activity.read','lead.assign'].includes(x)))return false;
  const append=!!cursor&&ui.salesFollowupsFor===employeeId,epoch=ui.epoch,request=++ui.salesFollowupsEpoch;ui.salesFollowupsRetryCursor=cursor||'';
  ui.salesFollowupsFor=employeeId;ui.salesFollowupsBusy=true;ui.salesFollowupsError='';if(!append)ui.salesFollowups=null;draw();
  try{
   const params=new URLSearchParams({view:'followups',employeeId,limit:'50'});if(cursor)params.set('cursor',cursor);
   const result=await employeeAuth.request('v1/sales/activity?'+params);
   if(epoch!==ui.epoch||request!==ui.salesFollowupsEpoch||!active()||state.page!=='salesMetrics'||ui.salesFollowupsFor!==employeeId)return false;
   const previous=ui.salesFollowups?.items||[],seen=new Set(previous.map(item=>item?.id).filter(Boolean)),page=(result.items||[]).filter(item=>{if(!item?.id||seen.has(item.id))return false;seen.add(item.id);return true;});ui.salesFollowups=append?{...result,items:[...previous,...page]}:{...result,items:page};ui.salesFollowupsRetryCursor='';return true;
  }catch(e){if(e.code==='INVALID_CURSOR'&&cursor&&epoch===ui.epoch&&request===ui.salesFollowupsEpoch&&state.page==='salesMetrics'&&ui.salesFollowupsFor===employeeId){ui.salesFollowups=null;ui.salesFollowupsRetryCursor='';return await salesFollowupsLoad(employeeId)}if(epoch===ui.epoch&&request===ui.salesFollowupsEpoch&&state.page==='salesMetrics'&&ui.salesFollowupsFor===employeeId)ui.salesFollowupsError=errorText(e);return false}
  finally{if(epoch===ui.epoch&&request===ui.salesFollowupsEpoch){ui.salesFollowupsBusy=false;if(state.page==='salesMetrics')draw()}}
 }
 function salesFollowupsToggle(employeeId){
  if(typeof employeeId!=='string'||!employeeId||!active()||!ui.user.permissions.some(x=>['audit.read','sales.activity.read','lead.assign'].includes(x)))return false;
  if(ui.salesFollowupsFor===employeeId){ui.salesFollowupsEpoch++;ui.salesFollowupsFor=null;ui.salesFollowups=null;ui.salesFollowupsBusy=false;ui.salesFollowupsError='';ui.salesFollowupsRetryCursor='';draw();return false}
  ui.salesFollowupsFor=employeeId;ui.salesFollowups=null;return salesFollowupsLoad(employeeId);
 }
 function salesFollowupsRetry(employeeId){if(ui.salesFollowupsFor!==employeeId)return false;return salesFollowupsLoad(employeeId,ui.salesFollowupsRetryCursor)}
 function salesFollowupsHtml(employeeId){
  const result=ui.salesFollowupsFor===employeeId?ui.salesFollowups:null,items=result?.items||[];
  if(ui.salesFollowupsBusy&&!items.length)return '<p class="muted" role="status">正在读取全部历史跟进记录…</p>';
  if(ui.salesFollowupsError)return `<p class="business-error" role="alert">${html(ui.salesFollowupsError)} <button type="button" class="btn small" onclick="event.stopPropagation();businessAPI.salesFollowupsRetry(${html(JSON.stringify(employeeId))})">重试</button></p>`;
  return `<div class="business-sales-followups"><div class="toolbar"><strong>全部历史跟进记录</strong><span class="muted">按时间从新到旧排列，不受统计日期筛选影响</span></div><div class="table-wrap"><table class="table"><thead><tr><th>时间</th><th>线索/学员</th><th>沟通方式</th><th>跟进内容</th><th>下次跟进</th></tr></thead><tbody>${items.map(item=>`<tr><td>${html(localDateTime(item.at)||'—')}</td><td>${html(item.leadName||item.leadId||'—')}</td><td>${html(item.channel||'—')}</td><td class="business-followup-note">${html(item.note||'—')}</td><td>${html(localDateTime(item.nextFollowAt)||'未约定')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无跟进记录</td></tr>'}</tbody></table></div>${result?.hasMore&&result?.nextCursor?`<button type="button" class="btn small" ${ui.salesFollowupsBusy?'disabled':''} onclick="event.stopPropagation();businessAPI.salesFollowupsMore(${html(JSON.stringify(employeeId))},${html(JSON.stringify(result.nextCursor))})">${ui.salesFollowupsBusy?'正在加载…':'加载更多跟进记录'}</button>`:''}</div>`;
 }
 function salesMetricsHtml(){
  const report=ui.salesReport,items=report?.items||[],canActivity=ui.user.permissions.some(x=>['audit.read','sales.activity.read','lead.assign'].includes(x)),canFollowups=canActivity,colspan=canActivity?10:9;
  return `<section class="card pad"><div class="toolbar"><strong>销售统计</strong><div class="filters"><label>开始日期<input class="input" type="date" value="${html(ui.salesReportFrom)}" onchange="businessAPI.salesReportDate('from',this.value)"></label><label>结束日期<input class="input" type="date" value="${html(ui.salesReportTo)}" onchange="businessAPI.salesReportDate('to',this.value)"></label><button class="btn primary" onclick="businessAPI.salesReportRefresh()">查询</button></div></div><p class="help">${html(report?.scope||'当前授权范围')} · ${html(report?.cohortDescription||'按线索分配批次统计')} · 来源为服务器聚合数据</p>${ui.salesReportBusy?'<p class="muted">正在读取销售统计…</p>':''}${ui.salesReportError?`<p class="business-error" role="alert">${html(ui.salesReportError)}</p>`:''}<div class="table-wrap"><table class="table business-table"><thead><tr><th>销售</th><th>分配线索</th><th>转化</th><th>转化率</th><th>实收</th><th>退款</th><th>净实收</th><th>平均转化时长</th><th>超时数/率</th>${canActivity?'<th>明细</th>':''}</tr></thead><tbody>${items.map(row=>{
   const sample=Number(row.assignedUnique)||0,converted=Number(row.convertedUnique)||0,overdue=Number(row.overdueUnique)||0,small=row.lowSample||sample<10,rate=sample?converted/sample*100:null,overdueRate=sample?overdue/sample*100:null,employee=html(JSON.stringify(row.employeeId)),expanded=canFollowups&&ui.salesFollowupsFor===row.employeeId,rowAttrs=canFollowups?`tabindex="0" role="button" aria-expanded="${expanded}" aria-label="${html(row.employeeName||row.employeeId)}跟进记录与统计明细" onclick="businessAPI.salesFollowupsToggle(${employee})" onkeydown="if(event.target===event.currentTarget&&(event.key==='Enter'||event.key===' ')){event.preventDefault();businessAPI.salesFollowupsToggle(${employee})}"`:'';
   return `<tr class="business-sales-row${canFollowups?' business-sales-row-clickable':''}" style="cursor:${canFollowups?'pointer':'default'}" ${rowAttrs}><td><span class="business-sales-name">${html(row.employeeName||row.employeeId)}</span>${row.archived?'<small class="business-sales-archived">离职归档</small>':''}${canFollowups?'<small>点击查看跟进记录</small>':''}</td><td>${sample}</td><td>${converted}</td><td>${small?`${converted} / ${sample} · 样本不足`:`${(Number(row.conversionRate)*100).toFixed(1)}%`}</td><td>${(Number(row.receivedMinor)||0)/100} 元</td><td>${(Number(row.refundedMinor)||0)/100} 元</td><td>${(Number(row.netReceivedMinor)||0)/100} 元</td><td>${row.avgHoursToConversion==null?'—':html(Number(row.avgHoursToConversion).toFixed(1))+' 小时'}${Number(row.conversionDurationCoverage)>0?`<small>${Number(row.conversionDurationCoverage)} 条转化有分配历史</small>`:''}</td><td>${overdue} / ${small?`${overdue} / ${sample} · 样本不足`:`${(Number(row.overdueRate)*100).toFixed(1)}%`}</td>${canActivity?`<td><button class="btn small" onclick="event.stopPropagation();businessAPI.salesActivity('${html(row.employeeId)}')">操作日志</button>${ui.salesActivityFor===row.employeeId&&ui.salesActivity?`<details onclick="event.stopPropagation()"><summary>转化原始率 ${rate==null?'—':rate.toFixed(1)+'%'} · 超时原始率 ${overdueRate==null?'—':overdueRate.toFixed(1)+'%'}</summary>${salesActivityHtml(ui.salesActivity)}</details>`:''}</td>`:''}</tr>${expanded?`<tr class="business-sales-followups-row"><td class="business-sales-followups-cell" colspan="${colspan}">${salesFollowupsHtml(row.employeeId)}</td></tr>`:''}`
  }).join('')||`<tr><td colspan="${colspan}" class="empty">${ui.salesReportBusy?'正在加载统计':'暂无当前授权范围内的统计数据'}</td></tr>`}</tbody></table></div><p class="help">${canFollowups?'点击销售行查看该员工全部历史跟进记录；此列表不受上方统计日期筛选影响。':'销售统计按上方日期范围展示。'}样本少于 10 条时不用于排名；金额口径遵循实收归属快照。</p></section>`;
 }

 function salesActivityHtml(result){const items=result?.items||[];return `<div class="table-wrap"><table class="table"><thead><tr><th>时间</th><th>线索</th><th>操作</th><th>内容</th></tr></thead><tbody>${items.map(item=>`<tr><td>${html(item.createdAt||item.at||'—')}</td><td>${html(item.leadName||item.leadId||'—')}</td><td>${html(item.action||item.type||'—')}</td><td>${item.summary&&typeof item.summary==='object'?resultHtml(item.summary):html(item.summary||item.outcome||'—')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">暂无操作事件</td></tr>'}</tbody></table></div>${result?.nextCursor?`<button class="btn small" ${ui.salesActivityBusy?'disabled':''} onclick="businessAPI.salesActivityMore(${html(JSON.stringify(ui.salesActivityFor))},${html(JSON.stringify(result.nextCursor))})">加载更多操作记录</button>`:''}`}

 function setupGuide(){return ''}

 const commonIds=['lead.create','lead.followup','enrollment.create','class.schedule','session.attendance','order.confirmReceipt'];
 function dashboard(){if(window.SiyueBusinessWorkbench)return window.SiyueBusinessWorkbench.render({...presentationContext(),canVisit:permissionCanVisit,setupGuide,leadTiming,leadConverted,leadArchived});const metrics=ui.data?.metrics,conversion=metrics?`<section class="card pad"><strong>我的销售转化</strong><p>${metrics.lowSample?`样本不足：${Number(metrics.ownLeads)||0} / ${Number(metrics.minimumSample)||10} 条；已转化 ${Number(metrics.converted)||0} 人`:`${(Number(metrics.conversionRate||0)*100).toFixed(1)}% · 已转化 ${Number(metrics.converted)||0} / ${Number(metrics.ownLeads)||0} 人`}</p><span class="help">累计本人归属线索；转化按首笔实收时的归属快照统计。</span></section>`:'';const values=[['线索',employeeAuth.has('lead.read')?dataRows('leads').length:'无权限'],['在读学生',employeeAuth.has('student.read')?new Set(dataRows('enrollments').filter(x=>['active','在读','已生效'].includes(x.status)).map(x=>x.studentId)).size:'无权限'],['待收款',employeeAuth.has('order.read')?dataRows('orders').filter(r=>!['cancelled','closed'].includes(r.status)&&Number(r.totalCents??r.amountCents??0)>Number(r.paidCents||0)).length:'无权限']];return `${setupGuide()}<section class="card business-stats">${values.map(([label,count])=>`<div><span>${label}</span><strong>${count}</strong></div>`).join('')}</section>${conversion}<section class="card pad"><div class="toolbar"><strong>常用操作</strong></div><div class="business-operation-grid">${ui.operations.filter(permitted).sort((a,b)=>commonIds.indexOf(a.id)<0?1:commonIds.indexOf(b.id)<0?-1:commonIds.indexOf(a.id)-commonIds.indexOf(b.id)).slice(0,6).map(op=>`<button class="btn" onclick="businessAPI.open('${html(op.id)}')">${html(op.label)}</button>`).join('')||'<p class="empty">当前账号没有可办理操作</p>'}</div></section>`}
 function scheduleRows(){return dataRows('classes').flatMap(c=>(c.schedule||[]).filter(s=>s.status!=='cancelled').map(s=>({c,s}))).sort((a,b)=>(a.s.date+a.s.time).localeCompare(b.s.date+b.s.time))}
 function scheduleSessionActions(seed){
  const c=dataRows('classes').find(c=>c.id===seed.classId),session=c?.schedule?.find(s=>s.id===seed.sessionId);if(!session||session.status==='cancelled')return '';
  const own=(session.substituteTeacherId||session.teacherId||c.teacherId)===ui.user.id,today=new Date(Date.now()+28800000).toISOString().slice(0,10),start=Date.parse(session.date+'T'+String(session.time).slice(0,5)+':00+08:00'),restricted=ui.user.roleIds?.includes('teacher')&&!ui.user.permissions.includes('session.move'),ids=['session.attendance.exceptions','session.record','session.reschedule.request','session.move','session.substitute','session.cancel'];
  return ids.map(id=>ui.operations.find(op=>op.id===id)).filter(op=>permitted(op)).filter(op=>op.id==='session.attendance.exceptions'?own&&session.date===today&&start<=Date.now():op.id==='session.reschedule.request'?own&&start>Date.now():op.id==='session.record'?(!restricted||own)&&start<=Date.now():!restricted&&start>Date.now()).map(op=>`<button type="button" class="btn small" onclick="businessAPI.open('${op.id}',${html(JSON.stringify(seed))})">${html(op.label)}</button>`).join('');
 }
 function scheduleHtml(){
  if(window.SiyueBusinessSchedule)return window.SiyueBusinessSchedule.render({...presentationContext(),selectedSession:ui.selectedSession,sessionActions:scheduleSessionActions});
  const rows=scheduleRows(),modes=[['teacher','老师'],['student','学生'],['room','教室'],['campus','校区']],mode=ui.scheduleMode;
  const entities=mode==='teacher'?(ui.data.directory||[]).filter(x=>x.roleIds?.includes('teacher')).map(x=>[x.id,x.name]):mode==='student'?dataRows('students').map(x=>[x.id,x.name]):mode==='campus'?dataRows('campuses').map(x=>[x.id,x.name]):[...new Map(rows.map(({c,s})=>[c.campusId+'|'+(s.room||c.room),[c.campusId+'|'+(s.room||c.room),nameOf('campuses',c.campusId)+' · '+(s.room||c.room)]])).values()];
  const member=(r,id)=>mode==='teacher'?(r.s.teacherId||r.c.teacherId)===id:mode==='student'?(Array.isArray(r.s.studentIds)?r.s.studentIds.includes(id):dataRows('enrollments').some(e=>e.studentId===id&&e.classId===r.c.id&&e.status!=='cancelled'&&e.status!=='withdrawn')):mode==='campus'?(r.s.campusId||r.c.campusId)===id:r.c.campusId+'|'+(r.s.room||r.c.room)===id;
  const filtered=rows.map((r,index)=>({...r,index})).filter(r=>(!ui.scheduleDate||r.s.date===ui.scheduleDate)&&(!ui.scheduleEntity||member(r,ui.scheduleEntity)));
  const controls=`<div class="business-tabs">${modes.map(([id,name])=>`<button class="${id===mode?'active':''}" onclick="businessAPI.scheduleFilter('scheduleMode','${id}')">${name}</button>`).join('')}</div><div class="toolbar"><select class="select" aria-label="课表对象" onchange="businessAPI.scheduleFilter('scheduleEntity',this.value)"><option value="">全部${modes.find(x=>x[0]===mode)[1]}</option>${entities.map(([id,name])=>`<option value="${html(id)}" ${id===ui.scheduleEntity?'selected':''}>${html(name)}</option>`).join('')}</select><input class="input" type="date" aria-label="课表日期" value="${html(ui.scheduleDate)}" onchange="businessAPI.scheduleFilter('scheduleDate',this.value)">${ui.operations.some(x=>x.id==='class.schedule'&&permitted(x))?'<button class="btn primary" onclick="businessAPI.open(\'class.schedule\')">班级排课</button>':''}</div>`;
  let content='';
  if(['room','campus'].includes(mode))content=`<div class="table-wrap"><table class="table business-table"><thead><tr><th>日期</th><th>时间</th><th>班级</th><th>老师</th><th>校区</th><th>教室</th></tr></thead><tbody>${filtered.map(r=>`<tr tabindex="0" role="button" onclick="businessAPI.selectSlot(${r.index})" onkeydown="if(event.key==='Enter')businessAPI.selectSlot(${r.index})"><td>${html(r.s.date)}</td><td>${html(r.s.time)}</td><td>${html(r.c.name)}</td><td>${html(human('teacherId',r.s.teacherId||r.c.teacherId))}</td><td>${html(nameOf('campuses',r.s.campusId||r.c.campusId))}</td><td>${html(r.s.room||r.c.room)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无课次</td></tr>'}</tbody></table></div>`;
  else {
   const lanes=[];for(const [id,name]of entities.filter(([id])=>!ui.scheduleEntity||id===ui.scheduleEntity))for(const date of [...new Set(filtered.filter(r=>member(r,id)).map(r=>r.s.date))])lanes.push({name,date,rows:filtered.filter(r=>r.s.date===date&&member(r,id))});
   const minutes=t=>{const parts=String(t).match(/\d{1,2}:\d{2}/g)||[];return parts.map(x=>{const [h,m]=x.split(':').map(Number);return h*60+m})};
   content=`<div class="caterpillar-legend"><span><i></i>待上课／待确认</span><span><i class="done"></i>已记录</span><span><i class="conflict"></i>时间冲突</span></div><div class="timeline-scroll"><div class="caterpillar-board"><div class="timeline-header"><div>${mode==='teacher'?'老师':'学生'} · 日期</div><div class="timeline-hours">${Array.from({length:13},(_,i)=>`<span style="left:${i/12*100}%">${String(i*2).padStart(2,'0')}:00</span>`).join('')}</div></div>${lanes.map(l=>{const positioned=l.rows.map(r=>({...r,range:minutes(r.s.time)})),ends=[];positioned.forEach(r=>{r.conflict=positioned.some(o=>o!==r&&o.range[0]<r.range[1]&&o.range[1]>r.range[0]);let lane=ends.findIndex(end=>end<=r.range[0]);if(lane<0)lane=ends.length;ends[lane]=r.range[1];r.lane=lane});return `<div class="caterpillar-lane"><div class="caterpillar-label"><strong>${html(l.name)}</strong><span>${html(l.date)}</span></div><div class="caterpillar-track" style="--tick:${100/24}%;height:${Math.max(1,ends.length)*96}px">${positioned.filter(r=>r.range.length===2).map(r=>`<button class="worm-segment ${r.conflict?'is-conflict':dataRows('attendance').some(a=>a.classId===r.c.id&&a.sessionId===r.s.id)?'is-done':''}" style="left:${r.range[0]/1440*100}%;width:${(r.range[1]-r.range[0])/1440*100}%;top:${r.lane*96}px" onclick="businessAPI.selectSlot(${r.index})" title="${html(r.c.name+' '+r.s.time)}"><b>${html(r.s.time)}</b><strong>${html(r.c.name)}</strong><span>${html(lessonLabel(r.c,r.s.lessonId))}</span><small>${html(r.s.room||r.c.room)}</small></button>`).join('')}</div></div>`}).join('')||'<div class="caterpillar-empty">暂无课次，请先建班并排课。</div>'}</div></div>`;
  }
  const selected=ui.selectedSlot===null?null:rows[ui.selectedSlot],actions=selected?`<section class="business-session-actions"><strong>${html(selected.c.name)} · ${html(selected.s.date)} ${html(selected.s.time)}</strong><div class="actions">${ui.operations.filter(op=>op.id.startsWith('session.')&&permitted(op)).map(op=>`<button class="btn small" onclick="businessAPI.sessionAction('${html(op.id)}')">${html(op.label)}</button>`).join('')}</div></section>`:'';
  return `<section class="card pad schedule-panel">${controls}${content}${actions}</section>`;
 }
